#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    int n = (int)readLong();
    long long left = readLong();
    vector<long long> a;
    a.reserve(n);
    for (int i = 0; i < n; i++) {
        long long v = readLong();
        if (v > 0) a.push_back(v);
    }
    sort(a.rbegin(), a.rend());
    if (a.empty() || left == 0) { puts("0"); return 0; }
    long long low = a.back(), answer = 0, c = 1, h = a[0];
    long long sz = (long long)a.size();
    // Flatten the top plateau down to each next distinct level; the minimum stays `low` meanwhile.
    while (c < sz && left > 0) {
        long long nxt = a[c], cap = c * (h - nxt);
        long long take = min(left, cap), q = take / c, r = take % c;
        answer += c * (q * (2 * h - q + 1) / 2) + r * (h - q) + take * low;
        left -= take;
        if (take < cap) { printf("%lld\n", answer); return 0; }
        h = nxt;
        c++;
    }
    // All c types are equal at height h: each full round earns c(2h-1)+1.
    long long take = min(left, c * (h - 1)), q = take / c, r = take % c;
    answer += q * (c * (2 * h - q) + 1);
    if (r) answer += 2 * (h - q) + (r - 1) * (2 * (h - q) - 1);
    left -= take;
    answer += 2 * left;
    printf("%lld\n", answer);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long left = nextLong();
        long[] a = new long[n];
        int sz = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            if (v > 0) a[sz++] = v;
        }
        a = Arrays.copyOf(a, sz);
        Arrays.sort(a); // ascending; index from the end for descending order
        if (sz == 0 || left == 0) { System.out.println(0); return; }
        long low = a[0], answer = 0, c = 1, h = a[sz - 1];
        // Flatten the top plateau down to each next distinct level; the minimum stays `low` meanwhile.
        while (c < sz && left > 0) {
            long nxt = a[sz - 1 - (int) c], cap = c * (h - nxt);
            long take = Math.min(left, cap), q = take / c, r = take % c;
            answer += c * (q * (2 * h - q + 1) / 2) + r * (h - q) + take * low;
            left -= take;
            if (take < cap) { System.out.println(answer); return; }
            h = nxt;
            c++;
        }
        // All c types are equal at height h: each full round earns c(2h-1)+1.
        long take = Math.min(left, c * (h - 1)), q = take / c, r = take % c;
        answer += q * (c * (2 * h - q) + 1);
        if (r != 0) answer += 2 * (h - q) + (r - 1) * (2 * (h - q) - 1);
        left -= take;
        answer += 2 * left;
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := int(readInt())
	left := readInt()
	a := make([]int64, 0, n)
	for i := 0; i < n; i++ {
		if v := readInt(); v > 0 {
			a = append(a, v)
		}
	}
	sort.Slice(a, func(i, j int) bool { return a[i] > a[j] })
	if len(a) == 0 || left == 0 {
		fmt.Println(0)
		return
	}
	low, answer, c, h := a[len(a)-1], int64(0), int64(1), a[0]
	sz := int64(len(a))
	// Flatten the top plateau down to each next distinct level; the minimum stays `low` meanwhile.
	for c < sz && left > 0 {
		nxt := a[c]
		limit := c * (h - nxt)
		take := min(left, limit)
		q, r := take/c, take%c
		answer += c*(q*(2*h-q+1)/2) + r*(h-q) + take*low
		left -= take
		if take < limit {
			fmt.Println(answer)
			return
		}
		h = nxt
		c++
	}
	// All c types are equal at height h: each full round earns c(2h-1)+1.
	take := min(left, c*(h-1))
	q, r := take/c, take%c
	answer += q * (c*(2*h-q) + 1)
	if r > 0 {
		answer += 2*(h-q) + (r-1)*(2*(h-q)-1)
	}
	left -= take
	answer += 2 * left
	fmt.Println(answer)
}
